UPDATE exercises SET prompt = 'Susun kalimat: "Kesadaran perusahaan terhadap keberlanjutan lingkungan sedang terus meningkat."', content = '{"romaji":"Kankyou e no hairyo ni taisuru kigyou no ishiki ga takamaritsutsu aru.","tokens":["企業の意識が","高まり","ある。","ざるを得ない。","環境配慮に対する","年々","つつ","高まった"],"target_translation":"Kesadaran perusahaan terhadap keberlanjutan lingkungan sedang terus meningkat."}'::jsonb, correct_answer = '["環境配慮に対する","企業の意識が","年々","高まり","つつ","ある。"]'::jsonb WHERE id = 'dff84a82-d1d1-4326-8803-5502bc74dd83';
UPDATE exercises SET prompt = 'Simulasi N2 (9/10): Dengarkan peringatan manajer kualitas. Apa risiko yang ia khawatirkan?', content = '{"options":[{"id":"opt_1","text":"Biaya produksi akan menjadi nol tanpa pemeriksaan"},{"id":"opt_2","text":"Pelanggan akan lebih cepat menerima produk sempurna"},{"id":"opt_3","text":"Pabrik akan menerima penghargaan kualitas internasional"},{"id":"opt_4","text":"Jika tahap inspeksi sebelum kirim dilewati, produk cacat bisa beredar dan memicu penarikan massal"}],"audio_text":"出荷前の検査工程を省略すれば、不良品が市場に流出して大規模なリコールに発展しかねません。"}'::jsonb, correct_answer = '{"selected_id":"opt_4"}'::jsonb WHERE id = '93fff7bf-a3bc-49c7-bd70-39489d4a3f5c';
