UPDATE exercises SET prompt = 'Simulasi N1 (1/10): Lengkapi kalimat formal berikut: 顧客データの流出が発覚する___、経営陣はようやく抜本的な安全対策に着手した。', content = '{"options":["に至って","とはいえ","なりに","に足る"],"translation":"Baru setelah kebocoran data pelanggan terungkap, manajemen akhirnya mulai menerapkan langkah keamanan mendasar.","sentence_template":"顧客データの流出が発覚する[blank]、経営陣はようやく抜本的な安全対策に着手した。"}'::jsonb, correct_answer = '{"selected":"に至って"}'::jsonb WHERE id = '1f79313b-f485-4df1-9145-c679f5e85994';
